	}

	if attr2.AgentLines <= 0 {
		t.Errorf("AgentLines = %d, should be > 0", attr2.AgentLines)
	}

	if attr2.AgentPercentage != 100 {
		t.Errorf("AgentPercentage = %.1f%%, want 100%% (only agent lines in this commit)",
			attr2.AgentPercentage)
	}
}

